window.kbPageData["views/entry/k-0672e13b123466d9"] = {"key":"entry/k-0672e13b123466d9","state":{"route":"entry/k-0672e13b123466d9"},"node":{"id":"k-0672e13b123466d9","mode":"k","title":"中央八项规定精神学习教育","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2025,"title":"中央八项规定精神学习教育","slug":"9a796f297faa"}],"directorySummary":"2.中央八项规定精神学习教育\n深入贯彻中央八项规定精神学习教育，是中共中央于 2025 年全国两会后启动、2025 年\n7 月底前基本结束，在全党开展的贯彻中央八项规定精神的学习教育。坚持聚焦主题、简约\n务实，不分批次、不划阶段，一体推进学查改，融入日常、抓在经常。\n——共产党员网","sources":[{"id":"c6c50fa6203838d2","label":"中央八项规定精神学习教育","topic":"年度政府工作","category":"时政","text":"2.中央八项规定精神学习教育\n深入贯彻中央八项规定精神学习教育，是中共中央于 2025 年全国两会后启动、2025 年\n7 月底前基本结束，在全党开展的贯彻中央八项规定精神的学习教育。坚持聚焦主题、简约\n务实，不分批次、不划阶段，一体推进学查改，融入日常、抓在经常。\n——共产党员网","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":51,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"7f367a44396a1a5d","label":"中央八项规定精神学习教育","topic":"年度政府工作","category":"时政","text":"中央八项规定精神学习教育\n学习教育于 2025 年全国两会后启动、7 月底前基本结束。要坚持坚持聚焦主题、简约\n务实，不分批次、不划阶段，一体推进学查改，融入日常、抓在经常。学习研讨要组织学习\n习近平总书记关于加强党的作风建设的重要论述和中央八项规定及其实施细则精神，总结学\n习深入贯彻中央八项规定精神的成效和经验，提高认识、增强信心，坚定不移抓好落实。查\n摆问题要通过对标对表查摆，充分运用纪检监察、巡视巡察、审计监督、财会监督、督促检\n查、调查研究、信访反映等途径，全面深入查找落实中央八项规定及其实施细则精神方面存\n在的问题。集中整治要坚持有什么问题就解决什么问题，什么问题突出就重点整治什么问题，\n立查立改、即知即改。开门教育要注重群众参与，接受群众监督，各级领导干部要带头走\n好新时代党的群众路线，组织党员、干部立足岗位，在推动高质量发展、加强基层治理、完\n成急难险重任务中担当作为、服务群众，让群众可感可及。\n——《关于在全党开展深入贯彻中央八项规定精神学习教育的通知》","source":{"doc":"6cbfb01fe723bba64b75","first":13,"last":13,"page":13,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-0672e13b123466d9":[]}};
